arguments.file_text:
@page "/apply"
@using sv_d18f2ab931d74b7e817e30259d9e3643.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var css = stepIndex == _currentStep ? "step active"
                : stepIndex < _currentStep ? "step completed"
                : "step future";
        <div class="@css" @onclick="() => GoToStep(stepIndex)">
            <span class="step-number">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(i < _currentStep ? "completed" : "")"></div>
        }
    }
</nav>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger">@_errorMessage</div>
}

@* Step Content *@
@if (_submitted)
{
    <div class="confirmation">
        <h2>&#10003; Application Submitted!</h2>
        <p>Your application has been received. Your application ID is <strong>@_applicationId</strong>.</p>
        <p>Thank you for applying!</p>
    </div>
}
else
{
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo()
            break;
        case 1:
            @RenderWorkHistory()
            break;
        case 2:
            @RenderReferences()
            break;
        case 3:
            @RenderCoverLetter()
            break;
        case 4:
            @RenderReview()
            break;
    }
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep = 0;
    private string _errorMessage = string.Empty;
    private bool _isProcessing = false;
    private bool _submitted = false;
    private int _applicationId = 0;

    // Step 1 state
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string _coverLetter = string.Empty;
    private const int CoverLetterMaxChars = 2000;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errorMessage = string.Empty;
            _currentStep = step;
        }
    }

    private async Task NextStep()
    {
        _errorMessage = string.Empty;
        _isProcessing = true;

        try
        {
            if (_currentStep == 0 && !await ValidatePersonalInfo()) return;
            if (_currentStep == 1 && !ValidateWorkHistory()) return;
            if (_currentStep == 2 && !ValidateReferences()) return;
            if (_currentStep == 3 && !ValidateCoverLetter()) return;

            _currentStep++;
        }
        finally
        {
            _isProcessing = false;
        }
    }

    private void PreviousStep()
    {
        _errorMessage = string.Empty;
        if (_currentStep > 0) _currentStep--;
    }

    private async Task<bool> ValidatePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(_fullName))
        {
            _errorMessage = "Full name is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_email))
        {
            _errorMessage = "Email is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_phone))
        {
            _errorMessage = "Phone is required.";
            return false;
        }
        if (string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Address is required.";
            return false;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
        if (!emailValid)
        {
            _errorMessage = "Please enter a valid email address.";
            return false;
        }

        return true;
    }

    private bool ValidateWorkHistory()
    {
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _errorMessage = "Each work entry must have a company name and job title.";
                return false;
            }
            if (entry.StartDate == default)
            {
                _errorMessage = "Each work entry must have a start date.";
                return false;
            }
        }
        return true;
    }

    private bool ValidateReferences()
    {
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                _errorMessage = "Each reference must have a name and email.";
                return false;
            }
        }
        return true;
    }

    private bool ValidateCoverLetter()
    {
        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Cover letter is required.";
            return false;
        }
