+                : "step future";
+        <div class="@css" @onclick="() => GoToStep(stepIndex)">
+            <span class="step-number">
+                @if (stepIndex < _currentStep)
+                {
+                    <span>&#10003;</span>
+                }
+                else
+                {
+                    @(stepIndex + 1)
+                }
+            </span>
+            <span class="step-label">@StepNames[stepIndex]</span>
+        </div>
+        @if (i < StepNames.Length - 1)
+        {
+            <div class="step-connector @(i < _currentStep ? "completed" : "")"></div>
+        }
+    }
+</nav>
+
+@if (!string.IsNullOrEmpty(_errorMessage))
+{
+    <div class="alert alert-danger">@_errorMessage</div>
+}
+
+@* Step Content *@
+@if (_submitted)
+{
+    <div class="confirmation">
+        <h2>&#10003; Application Submitted!</h2>
+        <p>Your application has been received. Your application ID is <strong>@_applicationId</strong>.</p>
+        <p>Thank you for applying!</p>
+    </div>
+}
+else
+{
+    @switch (_currentStep)
+    {
+        case 0:
+            @RenderPersonalInfo()
+            break;
+        case 1:
+            @RenderWorkHistory()
+            break;
+        case 2:
+            @RenderReferences()
+            break;
+        case 3:
+            @RenderCoverLetter()
+            break;
+        case 4:
+            @RenderReview()
+            break;
+    }
+}
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int _currentStep = 0;
+    private string _errorMessage = string.Empty;
+    private bool _isProcessing = false;
+    private bool _submitted = false;
+    private int _applicationId = 0;
+
+    // Step 1 state
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2 state
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3 state
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 state
+    private string _coverLetter = string.Empty;
+    private const int CoverLetterMaxChars = 2000;
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _errorMessage = string.Empty;
+            _currentStep = step;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        _errorMessage = string.Empty;
+        _isProcessing = true;
+
+        try
+        {
+            if (_currentStep == 0 && !await ValidatePersonalInfo()) return;
+            if (_currentStep == 1 && !ValidateWorkHistory()) return;
+            if (_currentStep == 2 && !ValidateReferences()) return;
+            if (_currentStep == 3 && !ValidateCoverLetter()) return;
+
+            _currentStep++;
+        }
+        finally
+        {
+            _isProcessing = false;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        _errorMessage = string.Empty;
+        if (_currentStep > 0) _currentStep--;
+    }
+
+    private async Task<bool> ValidatePersonalInfo()
+    {
+        if (string.IsNullOrWhiteSpace(_fullName))
+        {
+            _errorMessage = "Full name is required.";
+            return false;
+        }
+        if (string.IsNullOrWhiteSpace(_email))
+        {
+            _errorMessage = "Email is required.";
+            return false;
+        }
+        if (string.IsNullOrWhiteSpace(_phone))
+        {
+            _errorMessage = "Phone is required.";
+            return false;
+        }
+        if (string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "Address is required.";
+            return false;
+        }
+
+        var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+        if (!emailValid)
+        {
+            _errorMessage = "Please enter a valid email address.";
+            return false;
+        }
+
+        return true;
+    }
+
+    private bool ValidateWorkHistory()
+    {
+        foreach (var entry in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
+            {
+                _errorMessage = "Each work entry must have a company name and job title.";
+                return false;
+            }
+            if (entry.StartDate == default)
+            {
+                _errorMessage = "Each work entry must have a start date.";
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private bool ValidateReferences()
+    {
+        foreach (var r in _references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
+            {
+                _errorMessage = "Each reference must have a name and email.";
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private bool ValidateCoverLetter()
+    {
+        if (string.IsNullOrWhiteSpace(_coverLetter))
+        {
+            _errorMessage = "Cover letter is required.";
+            return false;
+        }
+        if (_coverLetter.Length > CoverLetterMaxChars)
+        {
+            _errorMessage = $"Cover letter must not exceed {CoverLetterMaxChars} characters.";
+            return false;
+        }
+        return true;
+    }
+
+    private async Task SubmitApplication()
+    {
+        _errorMessage = string.Empty;
+        _isProcessing = true;
+
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workEntries = _workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
+            var work = new WorkHistory(workEntries);
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var application = new JobApplication(personal, work, references, _coverLetter);
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isProcessing = false;
+        }
+    }
+
+    private void AddWorkEntry()
+    {
+        _workEntries.Add(new WorkEntryModel());
+    }
+
+    private void RemoveWorkEntry(WorkEntryModel entry)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.Remove(entry);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(ReferenceModel reference)
+    {
+        if (_references.Count > 2)
+            _references.Remove(reference);
+    }
+
+    // View model classes
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+
+    // Render methods
+    private RenderFragment RenderPersonalInfo() => __builder =>
+    {
+        <div class="step-content">
+            <h2>Personal Information</h2>
+            <div class="form-group">
+                <label>Full Name *</label>
+                <input type="text" @bind="_fullName" class="form-control" placeholder="Enter your full name" />
+            </div>
+            <div class="form-group">
+                <label>Email *</label>
+                <input type="email" @bind="_email" class="form-control" placeholder="Enter your email" />
+            </div>
+            <div class="form-group">
+                <label>Phone *</label>
+                <input type="tel" @bind="_phone" class="form-control" placeholder="Enter your phone number" />
+            </div>
+            <div class="form-group">
+                <label>Address *</label>
+                <input type="text" @bind="_address" class="form-control" placeholder="Enter your address" />
+            </div>
+            <div class="step-buttons">
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
+                    @(_isProcessing ? "Validating..." : "Next")
+                </button>
+            </div>
+        </div>
+    };
+
+    private RenderFragment RenderWorkHistory() => __builder =>
+    {
+        <div class="step-content">
+            <h2>Work History</h2>
+            @for (int i = 0; i < _workEntries.Count; i++)
+            {
+                var entry = _workEntries[i];
+                var index = i + 1;
+                <div class="work-entry-card">
+                    <div class="entry-header">
+                        <h4>Position @index</h4>
+                        @if (_workEntries.Count > 1)
+                        {
+                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
+                        }
+                    </div>
+                    <div class="form-group">
+                        <label>Company Name *</label>
+                        <input type="text" @bind="entry.Company" class="form-control" placeholder="Company name" />
+                    </div>
+                    <div class="form-group">
+                        <label>Job Title *</label>
+                        <input type="text" @bind="entry.Title" class="form-control" placeholder="Job title" />
+                    </div>
+                    <div class="form-row">
+                        <div class="form-group">
+                            <label>Start Date *</label>
+                            <input type="date" @bind="entry.StartDate" class="form-control" />
+                        </div>
+                        <div class="form-group">
+                            <label>End Date</label>
+                            <input type="date" @bind="entry.EndDate" class="form-control" disabled="@entry.IsCurrent" />
+                            <label class="checkbox-label">
+                                <input type="checkbox" @bind="entry.IsCurrent" /> Currently working here
+                            </label>
+                        </div>
+                    </div>
+                    <div class="form-group">
+                        <label>Description</label>
+                        <textarea @bind="entry.Description" class="form-control" rows="3" placeholder="Describe your responsibilities..."></textarea>
+                    </div>
+                </div>
+            }
+            <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
+            <div class="step-buttons">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+            </div>
+        </div>
+    };
+
+    private RenderFragment RenderReferences() => __builder =>
+    {
+        <div class="step-content">
+            <h2>References</h2>
+            @for (int i = 0; i < _references.Count; i++)
+            {
+                var reference = _references[i];
+                var index = i + 1;
+                <div class="reference-card">
+                    <div class="entry-header">
+                        <h4>Reference @index</h4>
+                        @if (_references.Count > 2)
+                        {
+                            <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(reference)">Remove</button>
+                        }
+                    </div>
+                    <div class="form-group">
+                        <label>Name *</label>
+                        <input type="text" @bind="reference.Name" class="form-control" placeholder="Reference name" />
+                    </div>
+                    <div class="form-group">
+                        <label>Relationship</label>
+                        <input type="text" @bind="reference.Relationship" class="form-control" placeholder="e.g., Former Manager" />
+                    </div>
+                    <div class="form-row">
+                        <div class="form-group">
+                            <label>Email *</label>
+                            <input type="email" @bind="reference.Email" class="form-control" placeholder="Email" />
+                        </div>
+                        <div class="form-group">
+                            <label>Phone</label>
+                            <input type="tel" @bind="reference.Phone" class="form-control" placeholder="Phone" />
+                        </div>
+                    </div>
+                </div>
+            }
+            @if (_references.Count < 3)
+            {
+                <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
+            }
+            <div class="step-buttons">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+            </div>
+        </div>
+    };
+
+    private RenderFragment RenderCoverLetter() => __builder =>
+    {
+        <div class="step-content">
+            <h2>Cover Letter</h2>
+            <div class="form-group">
+                <label>Write your cover letter *</label>
+                <textarea @bind="_coverLetter" @bind:event="oninput" class="form-control cover-letter-textarea" rows="12" placeholder="Tell us why you're a great fit for this role..."></textarea>
+                <div class="character-count @(_coverLetter.Length > CoverLetterMaxChars ? "over-limit" : "")">
+                    @_coverLetter.Length / @CoverLetterMaxChars characters
+                </div>
+            </div>
+            <div class="step-buttons">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">Next</button>
+            </div>
+        </div>
+    };
+
+    private RenderFragment RenderReview() => __builder =>
+    {
+        <div class="step-content">
+            <h2>Review & Submit</h2>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Personal Information</h3>
+                    <a href="javascript:void(0)" @onclick='() => GoToStep(0)'>Edit</a>
+                </div>
+                <dl>
+                    <dt>Full Name</dt><dd>@_fullName</dd>
+                    <dt>Email</dt><dd>@_email</dd>
+                    <dt>Phone</dt><dd>@_phone</dd>
+                    <dt>Address</dt><dd>@_address</dd>
+                </dl>
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Work History</h3>
+                    <a href="javascript:void(0)" @onclick='() => GoToStep(1)'>Edit</a>
+                </div>
+                @foreach (var entry in _workEntries)
+                {
+                    <div class="review-entry">
+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                        <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p>@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>References</h3>
+                    <a href="javascript:void(0)" @onclick='() => GoToStep(2)'>Edit</a>
+                </div>
+                @foreach (var r in _references)
+                {
+                    <div class="review-entry">
+                        <strong>@r.Name</strong> (@r.Relationship)<br />
+                        <span>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</span>
+                    </div>
+                }
+            </div>
+
+            <div class="review-section">
+                <div class="review-header">
+                    <h3>Cover Letter</h3>
+                    <a href="javascript:void(0)" @onclick='() => GoToStep(3)'>Edit</a>
+                </div>
+                <p class="cover-letter-preview">@_coverLetter</p>
+            </div>
+
+            <div class="step-buttons">
+                <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isProcessing">
+                    @(_isProcessing ? "Submitting..." : "Submit Application")
+                </button>
+            </div>
+        </div>
+    };
+}
+

